    internal sealed record SearchOutcome(
        SolverResult Result,
        object? SolverMetrics,
        object Policy,
        Dictionary<string, object?> LegacyMetrics,
        Dictionary<string, object?> RootCapture,
        string RootContinuationStamp,
        string RootLiveStamp,
