using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;
using MegaCrit.Sts2.Core.Models.Relics;
using MegaCrit.Sts2.Core.Nodes;
using MegaCrit.Sts2.Core.ValueProps;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertGenerationRecoveryClosureAsync(CombatState live, Player player)
    {
        foreach (RelicModel relic in player.Relics.ToArray())
            if (relic is not BoundPhylactery) await RelicCmd.Remove(relic);
        foreach (PotionModel? potion in player.PotionSlots.ToArray()) potion?.Discard();
        foreach (string id in new[] { "BEATING_REMNANT", "GAME_PIECE", "MEAL_TICKET" })
            await InjectRelicAsync(player, new() { RelicId = id, AddWithoutObtainedEffects = true });
        foreach (var enemy in live.Enemies)
        {
            await CreatureCmd.SetMaxHp(enemy, 500);
            await CreatureCmd.SetCurrentHp(enemy, 500);
        }
        int Bound(CombatPredictionSimulator sim) => StrategicHpRecoveryBound.ComponentHealingUpperBound(
            sim, player, 0, useReviewedSources: true);
        CombatRootSnapshot RequireProof()
        {
            var root = CombatRootSnapshot.Capture(live);
            if (root.CanCertifyRemainingHealing || root.UsesComponentHealingCertificate
                || !root.UsesPruningComponentHealingCertificate || root.InitialPruningHealingUpperBound != 0)
                throw new InvalidOperationException("Generation closure root/schedule qualification differs: "
                    + root.ComponentHealingRejection + "/" + root.PruningComponentHealingRejection);
            return root;
        }
        async Task Reset()
        {
            foreach (PowerModel power in live.Creatures.SelectMany(creature => creature.Powers).ToArray())
                if (power is not DieForYouPower) await PowerCmd.Remove(power);
            await ClearPlayerPilesAsync(player);
            await CreatureCmd.SetCurrentHp(player.Creature, 40);
            player.Creature.LoseBlockInternal(player.Creature.Block);
            player.Relics.OfType<BeatingRemnant>().Single()._damageReceivedThisTurn = 0;
            SetEnergy(player, 100);
        }
        CombatPredictionSimulator Play(CombatPredictionSimulator basis, CombatRootSnapshot root,
            CardModel nativeCard, IReadOnlyList<PlanCardChoice>? choices)
        {
            using var isolation = SimulationNotificationIsolation.Enter();
            var sim = basis.Fork();
            var combat = (SimulatedCombatState)sim.State.CombatState;
            var deaths = new ForkableSet<uint>();
            var target = nativeCard.TargetType == TargetType.AnyEnemy ? root.Enemies[0] : null;
            combat.BeginActionChoices(choices);
            try
            {
                bool completed;
                using (combat.BeginCardExecutionScope(deaths))
                    completed = sim.ManualPlay(sim.State.FindCard(nativeCard)!, target, out _);
                if (completed)
                {
                    if (!CorePowerSupport.ApplyEnemyDeathPowers(sim, combat, combat.KnownEnemies, deaths)
                        || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat))
                        throw new InvalidOperationException("Generation closure produced a later choice.");
                    sim.CheckWinCondition(root.StartTurnNumber);
                }
                else if (!sim.HasPendingChoice) throw new InvalidOperationException("Generation closure card refused.");
            }
            finally { combat.EndActionChoices(); }
            return sim;
        }
        async Task NativePlay(CardModel card, IReadOnlyList<PlanCardChoice>? choices)
        {
            using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12));
            using var session = NativeChoiceRuntime.Begin(live, player, "test:generation-recovery-closure");
            session.SetPlanAndStartDriving(NGame.Instance!, choices ?? [], deadline.Token);
            var target = card.TargetType == TargetType.AnyEnemy ? live.Enemies[0] : null;
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), card),
                () => { if (!card.TryManualPlay(target)) throw new InvalidOperationException("Native generation closure card refused: " + card.Id.Entry); }, deadline.Token);
            await session.AwaitProducerAndCompleteAsync(action.CompletionTask).WaitAsync(deadline.Token);
        }
        void EqualNative(CombatPredictionSimulator sim, CombatRootSnapshot root, string label)
        {
            string expected = ContinuationStamp.CapturePredicted(player, sim, root.StartTurnNumber,
                root.Forecast, root.StartTurnNumber).StateText;
            string actual = ContinuationStamp.CaptureLive(live).StateText;
            if (expected != actual) throw new InvalidOperationException(label + " native full continuation/RNG differs:\n"
                + ContinuationStamp.CapturePredicted(player, sim, root.StartTurnNumber,
                    root.Forecast, root.StartTurnNumber).DescribeFirstDifference(ContinuationStamp.CaptureLive(live)));
            if (Bound(sim) != 0) throw new InvalidOperationException(label + " left the finite generation closure.");
        }
        int nativeCases = 0;
        string[] nativeCardIds = _request.ScenarioId == "GENERATION-RECOVERY-TAIL" ? []
            : ["CALL_OF_THE_VOID", "CAPTURE_SPIRIT", "DANSE_MACABRE", "HIDDEN_GEM",
                "PANIC_BUTTON", "REAPER_FORM", "SCULPTING_STRIKE", "SOW", "THE_SCYTHE"];
        foreach (string id in nativeCardIds)
        foreach (int upgrade in new[] { 0, 1 })
        {
            await Reset();
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand", UpgradeLevels = upgrade,
                TreatAsDeckCard = id == "THE_SCYTHE" });
            await InjectCardAsync(live, player, new() { CardId = "STRIKE_NECROBINDER", Pile = "Hand" });
            foreach (string draw in new[] { "STRIKE_NECROBINDER", "DEFEND_NECROBINDER", "STRIKE_NECROBINDER", "WOUND" })
                await InjectCardAsync(live, player, new() { CardId = draw, Pile = "Draw" });
            CardModel card = FindActualHandCard(player, id, 0);
            if (upgrade == 1 && id is not "SCULPTING_STRIKE") card.BaseReplayCount = 1;
            var root = RequireProof();
            var parent = root.ForkSimulator();
            string parentBefore = DescribeContinuationContractState(parent, root, player);
            string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
            IReadOnlyList<PlanCardChoice>? choices = null;
            if (id == "SCULPTING_STRIKE")
            {
                var discovery = Play(parent, root, card, null);
                var request = ((SimulatedCombatState)discovery.State.CombatState).PendingTurnStartChoice!;
                choices = [CardChoiceSupport.BuildChoices(request.Spec!, SolverDisplayNames.Capture(live), 32, 32)
                    .First(choice => choice.Cards.Any(selected => selected.CardId == "STRIKE_NECROBINDER"))];
            }
            var expected = Play(parent, root, card, choices);
            string expectedState = DescribeContinuationContractState(expected, root, player);
            var children = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
            Parallel.For(0, children.Length, index =>
            {
                var child = Play(children[index], root, card, choices);
                if (DescribeContinuationContractState(child, root, player) != expectedState || Bound(child) != 0)
                    throw new InvalidOperationException(id + " parallel full state/history/RNG or bound differs.");
            });
            if (DescribeContinuationContractState(parent, root, player) != parentBefore
                || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
                throw new InvalidOperationException(id + " changed parent/live state.");
            await NativePlay(card, choices?.Select(choice => choice with { SourceId = id }).ToArray());
            EqualNative(expected, root, id + "+" + upgrade);
            if (id == "THE_SCYTHE")
            {
                int increased = (5 + 2 * upgrade) * (1 + card.BaseReplayCount);
                var predicted = (TheScythe)expected.State.FindCard(card)!.Preview;
                if (predicted.IncreasedDamage != increased || ((TheScythe)card.DeckVersion!).IncreasedDamage != increased
                    || ((SimulatedCombatState)expected.State.CombatState).GrowthRewards.TheScythe != 1 + card.BaseReplayCount)
                    throw new InvalidOperationException("Scythe combat/permanent growth count differs.");
            }
            if (id == "CALL_OF_THE_VOID")
            {
                using (SimulationNotificationIsolation.Enter())
                    if (TurnStartPowerSupport.TriggerBeforeHandDraw(expected, (SimulatedCombatState)expected.State.CombatState, player, new(null)))
                        throw new InvalidOperationException("Call of the Void generated a choice.");
                await player.Creature.Powers.OfType<CallOfTheVoidPower>().Single()
                    .BeforeHandDraw(player, new BlockingPlayerChoiceContext(), live);
                EqualNative(expected, root, "CallOfTheVoid:RepeatedNativeGeneration");
            }
            if (id is "REAPER_FORM" or "DANSE_MACABRE")
            {
                if (id == "DANSE_MACABRE")
                {
                    CardModel strike = FindActualHandCard(player, "STRIKE_NECROBINDER", 0);
                    strike.EnergyCost.AddThisCombat(1);
                    expected.State.FindCard(strike)!.MutablePreview.EnergyCost.AddThisCombat(1);
                }
                CardModel follow = FindActualHandCard(player, "STRIKE_NECROBINDER", 0);
                expected = Play(expected, root, follow, null);
                await NativePlay(follow, null);
                EqualNative(expected, root, id + ":TriggeredPower");
            }
            _completedChecks.Add($"GenerationRecoveryClosure:{id}+{upgrade}:NativeFullContinuationRNG:16ForkHistoryParentLive:ZeroRecovery:PruningOnly");
            nativeCases++;
        }

        await Reset();
        await InjectCardAsync(live, player, new() { CardId = "STRIKE_NECROBINDER", Pile = "Hand" });
        var damageRoot = RequireProof(); var damageParent = damageRoot.ForkSimulator(); var damaged = damageParent.Fork();
        string damageBefore = DescribeContinuationContractState(damageParent, damageRoot, player);
        foreach (int amount in new[] { 7, 25, 3 })
        {
            using (SimulationNotificationIsolation.Enter())
                damaged.Damage(player.Creature, amount, ValueProp.Unblockable | ValueProp.Unpowered, live.Enemies[0]);
            await CreatureCmd.Damage(new BlockingPlayerChoiceContext(), player.Creature, amount,
                ValueProp.Unblockable | ValueProp.Unpowered, live.Enemies[0]);
            EqualNative(damaged, damageRoot, "BeatingRemnant:" + amount);
        }
        if (damaged.State.GetCreature(player.Creature).CurrentHp != 20)
            throw new InvalidOperationException("Beating Remnant did not cap the turn at 20 HP loss.");
        using (SimulationNotificationIsolation.Enter())
            if (!TurnStartRelicSupport.TriggerBeforeSideTurnStart(damaged, (SimulatedCombatState)damaged.State.CombatState, [player.Creature]))
                throw new InvalidOperationException("Beating Remnant reset opened a choice.");
        await player.Relics.OfType<BeatingRemnant>().Single().BeforeSideTurnStart(
            new BlockingPlayerChoiceContext(), CombatSide.Player, [player.Creature], live);
        EqualNative(damaged, damageRoot, "BeatingRemnant:TurnReset");
        if (DescribeContinuationContractState(damageParent, damageRoot, player) != damageBefore)
            throw new InvalidOperationException("Beating Remnant changed frozen parent.");
        _completedChecks.Add($"GenerationRecoveryClosure:NativeCardCases={nativeCases}:"
            + (nativeCases != 0 ? "GamePiecePowerDraw:" : string.Empty)
            + "BeatingRemnantDamageCapReset:MealTicketCombatRoomExcluded");

        await Reset();
        foreach (string id in new[] { "THE_SCYTHE", "OFFERING", "BLOODLETTING", "STRIKE_NECROBINDER" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand", TreatAsDeckCard = id == "THE_SCYTHE" });
        await CreatureCmd.SetCurrentHp(live.Enemies[0], 5);
        // Keep exactly one enemy active for the complete legal growth witness.
        foreach (var enemy in live.Enemies.Skip(1).ToArray())
            await CreatureCmd.Kill(enemy, force: true);
        var growthRoot = RequireProof();
        var policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null) with
        {
            VerifyIncrementalSearch = true, FixedBudget = false, MaxDegreeOfParallelism = 2,
            GrowthBudgets = default, GrowthOpportunityTargets = GrowthOpportunityTargets.UnboundedForTesting("scythe_growth"),
            PotionPolicy = SolverPotionPolicy.Disabled, PotionStrategy = new(SolverPotionPolicy.Disabled, []),
            RelicTargets = [], PrimaryIncumbents = new(), StopAtAcceptableBattleHpLoss = false,
        };
        string growthLiveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var growthNames = SolverDisplayNames.Capture(live);
        var growthDamage = BattleDamageTracker.Observe(live);
        using var growthDeadline = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        _completedChecks.Add(await Task.Run(() => CombatBeamSolver.AssertScytheRecoveryEdgesForTesting(
            growthRoot, growthNames, growthDamage, policy, growthDeadline.Token)));
        if (ContinuationStamp.CaptureLive(live).StateText != growthLiveBefore)
            throw new InvalidOperationException("Scythe incumbent proof changed live state.");
    }
}

internal sealed partial class CombatBeamSolver
{
    internal static string AssertScytheRecoveryEdgesForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy, CancellationToken token)
    {
        using var isolation = SimulationNotificationIsolation.Enter();
        SearchNode Card(CombatBeamSolver solver, SearchNode node, string id) => solver.CostChildForTesting(node,
            solver.PrepareCardActions(node).First(candidate => candidate.Action.CardId == id).Action);
        var publisher = new CombatBeamSolver(root, names, damage, policy, token);
        var opening = CreateOpeningSearchSeed(publisher.Replay([]));
        var winner = Card(publisher, opening, "THE_SCYTHE");
        if (!winner.Snapshot.AllEnemiesDead || winner.Snapshot.HasRisk || winner.Snapshot.GrowthRewards.TheScythe != 1
            || winner.Snapshot.StrategicHpCredit != 0)
            throw new InvalidOperationException("No complete zero-credit Scythe growth winner.");
        publisher.TightenPrimarySearchIncumbentAtTurnLayer([winner], 1);
        var consumer = new CombatBeamSolver(root, names, damage, policy, token);
        var hurt = Card(consumer, Card(consumer, CreateOpeningSearchSeed(consumer.Replay([])), "OFFERING"), "BLOODLETTING");
        if (hurt.IsTerminal || consumer.ApplyPrimaryIncumbentBound([hurt]).Count != 0
            || consumer.ApplyPrimaryIncumbentBound([opening]).Count != 1)
            throw new InvalidOperationException("Scythe strict worse-HP pruning or equal-HP preservation differs.");
        var guarded = new CombatBeamSolver(root, names, damage,
            policy with { GrowthBudgets = new GrowthValues(TheScythe: 1) }, token);
        if (guarded.CanUseExpandedHpDominance || guarded.ApplyPrimaryIncumbentBound([hurt]).Count != 1)
            throw new InvalidOperationException("Positive Scythe growth credit was pruned by HP alone.");
        return "GenerationRecoveryClosure:ScytheCompleteGrowthWinner:ZeroCreditStrictWorseHpPruned:EqualHpKept:PositiveCreditKept:IncrementalReplay";
    }
}

