using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.ValueProps;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertLazyRecoveryBoundAsync(CombatState live, Player player)
    {
        await CreatureCmd.SetCurrentHp(player.Creature, 40);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        SolverDisplayNames names = SolverDisplayNames.Capture(live);
        BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
        SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null);
        string before = ContinuationStamp.CaptureLive(live).StateText;
        _completedChecks.Add(await Task.Run(() => CombatBeamSolver.AssertLazyRecoveryBoundForTesting(root, names, damage, policy)));
        if (ContinuationStamp.CaptureLive(live).StateText != before)
            throw new InvalidOperationException("Lazy recovery proof changed live state.");
    }
}

internal sealed partial class CombatBeamSolver
{
    internal static string AssertLazyRecoveryBoundForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy)
    {
        using var isolation = SimulationNotificationIsolation.Enter();
        var evaluator = new CombatBeamSolver(root, names, damage, policy);
        var parent = root.ForkSimulator();
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(root.PlayerIdentity,
            sim, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
        string before = State(parent);
        List<SimulationSnapshot> snapshots = [];
        foreach (int loss in new[] { 0, 5, 12, 38 })
        foreach (int recovered in new[] { 0, 3 })
        {
            var sim = parent.Fork();
            sim.Damage(root.PlayerIdentity.Creature, loss, ValueProp.Unblockable | ValueProp.Unpowered, root.Enemies[0]);
            sim.Heal(root.PlayerIdentity.Creature, recovered);
            snapshots.Add(evaluator.Snapshot(sim, root.StartTurnNumber, 1, 0,
                SearchBoundaryReason.None, new ForkableSet<uint>()));
        }
        int cases = 0, originalQueries = 0, lazyQueries = 0;
        var snapshotStates = snapshots.Select(snapshot => State(snapshot.Simulator)).ToArray();
        try
        {
            foreach (BossHpRelief relief in Enum.GetValues<BossHpRelief>())
            foreach (int hp in new[] { -5, 0, 5, 12, 40 })
            foreach (int? cost in new int?[] { null, 0, 5 })
            foreach (int healing in new[] { 0, 3, 100, int.MaxValue })
            foreach (int flags in Enumerable.Range(0, 64))
            {
                bool certified = (flags & 1) != 0, allowTurn = (flags & 2) != 0,
                    pruneEqual = (flags & 4) != 0, preserveCost = (flags & 8) != 0,
                    requireProof = (flags & 16) != 0, strictCost = (flags & 32) != 0;
                PrimarySearchIncumbent witness = new(hp, 3, cost);
                List<SearchNode> input = snapshots.Select((snapshot, index) => new SearchNode(
                    null, 0, 0, 0, index % 3 + 2, SearchRouteTraits.None, 0,
                    snapshot.Score, snapshot.StateKey, snapshot.HasRisk, SearchBoundaryReason.None,
                    index % 2 == 0, null, snapshot, null!)).ToList();
                SearchNode[] original = input.ToArray();
                // The pre-optimization evaluation order is the oracle. In
                // particular unknown recovery must still retain the branch.
                List<SearchNode> expected = [];
                int expectedCertifiedPruned = 0;
                foreach (SearchNode node in input)
                {
                    originalQueries++;
                    if (requireProof && healing == int.MaxValue) { expected.Add(node); continue; }
                    int effective = requireProof ? healing : Math.Min(healing, node.Snapshot.FutureHealPotential);
                    bool closed = CanPruneEqualHpWithPotionCost(node.Snapshot, witness, preserveCost);
                    if ((!strictCost || closed) && ShouldPruneByPrimaryIncumbent(
                        StrategicHpLowerBound(node.Snapshot, relief, effective), node.Turn, witness,
                        allowTurn && closed, pruneEqual && !node.IsTerminal && !node.Snapshot.HasRisk && closed))
                    {
                        if (certified && !ShouldPruneByPrimaryIncumbent(
                            StrategicHpLowerBound(node.Snapshot, relief, healing), node.Turn, witness,
                            allowTurn && closed, pruneEqual && !node.IsTerminal && !node.Snapshot.HasRisk && closed))
                            expectedCertifiedPruned++;
                        continue;
                    }
                    expected.Add(node);
                }
                var actual = ApplyPrimaryIncumbentBoundCore(input, witness, out int pruned, relief, certified,
                    _ => { lazyQueries++; return healing; }, out int certifiedPruned,
                    allowTurn, pruneEqual, preserveCost, requireProof, strictCost);
                if (!actual.SequenceEqual(expected, ReferenceEqualityComparer.Instance)
                    || !input.SequenceEqual(original, ReferenceEqualityComparer.Instance)
                    || pruned != input.Count - expected.Count || certifiedPruned != expectedCertifiedPruned
                    || pruned == 0 && !ReferenceEquals(actual, input))
                    throw new InvalidOperationException($"Lazy recovery differs: relief={relief}, hp={hp}, cost={cost}, healing={healing}, flags={flags}, pruned={pruned}, certified={certifiedPruned}/{expectedCertifiedPruned}.");
                cases++;
            }
            if (lazyQueries >= originalQueries || State(parent) != before
                || !snapshots.Select(snapshot => State(snapshot.Simulator)).SequenceEqual(snapshotStates))
                throw new InvalidOperationException("Lazy recovery did not omit queries, or changed branch/parent state.");
        }
        finally { foreach (var snapshot in snapshots) snapshot.ReleaseSimulator(); }
        return $"LazyRecoveryBound:Cases={cases}:OriginalQueries={originalQueries}:LazyQueries={lazyQueries}:"
            + "NativeBranchSnapshots:BossRelief:UnknownHealing:CostAndTurnGuards:OrderIdentityCounters:ParentLiveRNGIsolation";
    }
}

